import { strict as assert } from "node:assert";
import { readFileSync } from "node:fs";
import { describe, it } from "node:test";

import { parseElfSymbols, sha256Hex, verifyElfHash } from "../../src/elf/index.js";
import { parseTraceFiles, traceElfSha256 } from "../../src/trace/index.js";
import { formatDetail } from "../../web/ui/panes/events-rows.js";

// Integration tests for committed ELF identity fixtures generated by
// scripts/gen-elf-id-fixture.ts. Tests verify the full ELF loading pipeline:
// parsing with `{ elf }`, preserving the symbolizer on the model, and resolving
// caller stack frames to symbol names in the Detail column, while ensuring
// fixture hashes remain synchronized.

const ELF = new Uint8Array(readFileSync("test/fixtures/elf/demo-app.elf"));
const SVDAT = new Uint8Array(readFileSync("test/fixtures/traces/elf-id.svdat"));

describe("ELF-id fixtures", () => {
  it("matches the embedded trace ELF_SHA256 with the committed ELF hash", async () => {
    const traceHash = traceElfSha256(parseTraceFiles([SVDAT]));
    assert.ok(traceHash, "fixture trace carries no ELF_SHA256 — regenerate it");
    assert.equal(verifyElfHash(traceHash, await sha256Hex(ELF)), "match");
    assert.equal(parseElfSymbols(ELF).symbolCount, 3);
  });

  it("preserves the symbolizer on model.elf when parsed with { elf }", () => {
    const symbols = parseElfSymbols(ELF);
    const plain = parseTraceFiles([SVDAT]);
    assert.equal(plain.elf, undefined); // no ELF → no symbolizer

    const symbolized = parseTraceFiles([SVDAT], { elf: symbols });
    assert.equal(symbolized.elf, symbols);
    assert.equal(symbolized.events.length, plain.events.length); // elf adds no events
  });

  it("resolves heap allocation caller addresses to symbol names when ELF symbols are loaded", () => {
    const symbols = parseElfSymbols(ELF);
    const model = parseTraceFiles([SVDAT], { elf: symbols });
    const heap = model.events.find((e) => e.name === "esp_sysview_heap_trace_alloc");
    assert.ok(heap, "fixture has no heap alloc event — regenerate it");

    // Without symbols: numeric hex. With the model symbolizer: resolved symbol names.
    assert.match(formatDetail(heap), /callers=\[0x42000110, 0x42000210\]/);
    const detail = formatDetail(heap, undefined, model.elf);
    assert.match(detail, /callers=\[0x42000110 \(app_main\+0x10\), 0x42000210 \(loop_task\+0x10\)\]/);
  });
});
